package com.pulselens.analytics.controller;
import com.pulselens.analytics.entity.AppUser;import com.pulselens.analytics.repository.UserRepository;import jakarta.servlet.http.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.authentication.*;import org.springframework.security.core.Authentication;import org.springframework.security.core.context.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final PasswordEncoder encoder;private final AuthenticationManager manager;public AuthController(UserRepository u,PasswordEncoder e,AuthenticationManager m){users=u;encoder=e;manager=m;}
 public record Register(@NotBlank @Size(min=2,max=120) String fullName,@NotBlank @Size(min=3,max=60) String username,@Email @NotBlank String email,@NotBlank @Size(min=8,max=100) String password,String country){}public record Login(@Email @NotBlank String email,@NotBlank String password){}
 @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.findByEmailIgnoreCase(r.email()).isPresent())return ResponseEntity.badRequest().body(Map.of("message","An account with this email already exists."));if(users.findByUsernameIgnoreCase(r.username()).isPresent())return ResponseEntity.badRequest().body(Map.of("message","That username is already taken."));if(!r.password().matches("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[^A-Za-z\\d]).{8,}$"))return ResponseEntity.badRequest().body(Map.of("message","Password needs 8+ characters, uppercase, lowercase, a number and a symbol."));AppUser u=new AppUser();u.setFullName(r.fullName().trim());u.setUsername(r.username().trim());u.setEmail(r.email().trim().toLowerCase());u.setCountry(r.country());u.setPasswordHash(encoder.encode(r.password()));u.setRole("USER");users.save(u);return ResponseEntity.status(201).body(Map.of("message","Account created. Please sign in."));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Login r,HttpServletRequest req,HttpServletResponse res){try{Authentication a=manager.authenticate(new UsernamePasswordAuthenticationToken(r.email().trim().toLowerCase(),r.password()));SecurityContext c=SecurityContextHolder.createEmptyContext();c.setAuthentication(a);SecurityContextHolder.setContext(c);new HttpSessionSecurityContextRepository().saveContext(c,req,res);AppUser u=users.findByEmailIgnoreCase(r.email()).orElseThrow();return ResponseEntity.ok(map(u));}catch(Exception e){return ResponseEntity.status(401).body(Map.of("message","Invalid email or password."));}}
 @GetMapping("/me") public ResponseEntity<?> me(Authentication a){if(a==null)return ResponseEntity.status(401).body(Map.of("message","Not signed in"));return users.findByEmailIgnoreCase(a.getName()).<ResponseEntity<?>>map(u->ResponseEntity.ok(map(u))).orElseGet(()->ResponseEntity.status(401).body(Map.of("message","Not signed in")));}
 @PostMapping("/logout") public Map<String,String> logout(HttpServletRequest req){SecurityContextHolder.clearContext();HttpSession s=req.getSession(false);if(s!=null)s.invalidate();return Map.of("message","Signed out");}
 private Map<String,Object> map(AppUser u){Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.getId());m.put("fullName",u.getFullName());m.put("username",u.getUsername());m.put("email",u.getEmail());m.put("role",u.getRole());m.put("country",Objects.toString(u.getCountry(),""));m.put("createdAt",u.getCreatedAt());return m;}}
